import 'hazard.dart';
import 'package_type.dart';

/// All inputs needed to deterministically run one shift. Generated by
/// [DifficultyService] (or [DailySeed] for daily challenges) and consumed
/// by the Flame world.
class ShiftConfig {
  const ShiftConfig({
    required this.id,
    required this.seed,
    required this.duration,
    required this.targetScore,
    required this.spawnInterval,
    required this.spawnIntervalJitter,
    required this.allowedTypes,
    required this.allowedHazards,
    required this.maxConcurrentPackages,
    required this.beltSpeedMultiplier,
    required this.modifiers,
    required this.isDaily,
  });

  final String id;
  final int seed;
  final Duration duration;
  final int targetScore;
  final Duration spawnInterval;
  final Duration spawnIntervalJitter;
  final List<PackageType> allowedTypes;
  final List<HazardKind> allowedHazards;
  final int maxConcurrentPackages;
  final double beltSpeedMultiplier;
  final Set<ShiftModifier> modifiers;
  final bool isDaily;
}

enum ShiftModifier {
  blackout,
  doubleStamps,
  vipOnly,
  noPriority,
  fastBelts;

  String get key => name;
}
